export const config={id:'overprint-studio',title:'两色之间',subtitle:'OVERPRINT STUDIO / 08',description:'一张想象中的植物印样，由暖橙和靛蓝两块色版逐次叠印。调节套准偏移，观察边缘错位与色块重叠；这是程序图形示意，不是印刷设备模拟。',category:'interactive',useCase:'视觉设计实验',accent:'#d85b38',duration:12,parameter:{label:'套准偏移',min:0,max:18,step:1,value:5,unit:'px'}};
export function registration(v){return Math.max(0,Math.min(18,Number.isFinite(v)?v:5))}
export function printState(t){let u=((t%12)+12)%12;return {reveal:u<1?0:u<5?(u-1)/4:u<9?1:Math.max(0,(12-u)/3),phase:u<1?'准备色版':u<5?'第二色叠印':u<9?'停留观察':'回到纸面'}}
function petal(ctx,x,y,rot,scale=1){ctx.save();ctx.translate(x,y);ctx.rotate(rot);ctx.scale(scale,scale);ctx.beginPath();ctx.moveTo(0,0);ctx.bezierCurveTo(-28,-15,-50,-75,0,-98);ctx.bezierCurveTo(45,-80,31,-20,0,0);ctx.fill();ctx.restore()}
function botanical(ctx,color,dx=0){ctx.save();ctx.translate(dx,0);ctx.fillStyle=color;ctx.strokeStyle=color;ctx.lineWidth=8;ctx.lineCap='round';for(let j=0;j<3;j++){const x=410+j*115;ctx.beginPath();ctx.moveTo(530,603);ctx.bezierCurveTo(490,490,x,415,x,275+j*22);ctx.stroke();for(let i=0;i<4;i++){let yy=324+i*53+j*15;petal(ctx,x+(530-x)*(i/7),yy,-.8,.55);petal(ctx,x+(530-x)*(i/7),yy+.7,.8,.55)}}ctx.beginPath();ctx.moveTo(404,514);ctx.lineTo(656,514);ctx.lineTo(624,653);ctx.lineTo(439,653);ctx.closePath();ctx.fill();ctx.restore()}
export function render(ctx,{t,value,width,height}){ctx.save();ctx.scale(width/1200,height/800);ctx.fillStyle='#e9e3d3';ctx.fillRect(0,0,1200,800);ctx.fillStyle='#f7f1df';ctx.fillRect(90,55,1020,690);ctx.strokeStyle='#c6baa5';ctx.lineWidth=1;ctx.strokeRect(90.5,55.5,1020,690);let s=printState(t),reg=registration(value);
ctx.fillStyle='#373d44';ctx.font='13px monospace';ctx.fillText('FIELD NOTES / TWO-COLOUR STUDY',140,104);ctx.fillStyle='#33475a';ctx.font='600 26px serif';ctx.fillText('Leave a little room for imperfection.',140,147);
ctx.fillStyle='#e77b48';ctx.beginPath();ctx.arc(712,353,164,0,Math.PI*2);ctx.fill();ctx.fillStyle='#efb177';ctx.fillRect(294,380,478,235);botanical(ctx,'#d76339');
ctx.save();ctx.beginPath();ctx.rect(210,180,710,490*s.reveal);ctx.clip();ctx.globalCompositeOperation='multiply';botanical(ctx,'#3e708b',reg);ctx.fillStyle='#497995';ctx.beginPath();ctx.arc(756+reg,387,128,0,Math.PI*2);ctx.fill();ctx.fillStyle='#4a7992';for(let y=440;y<614;y+=15){ctx.fillRect(280+reg,y,193,4)}ctx.restore();
// Deterministic grain is synthesized here, never sampled from a print.
ctx.fillStyle='#f5eddb';ctx.globalAlpha=.25;for(let i=0;i<1600;i++){let x=250+(i*73%653),y=200+(i*131%470);ctx.fillRect(x,y,1.4,1.4)}ctx.globalAlpha=1;
if(s.reveal>0&&s.reveal<1){const y=180+490*s.reveal;ctx.fillStyle='#2a3f4d';ctx.fillRect(215,y-3,680,7);ctx.fillStyle='#6b827e';ctx.fillRect(197,y-8,18,18);ctx.fillRect(895,y-8,18,18)}
ctx.strokeStyle='#87928e';ctx.lineWidth=1;for(let [x,y] of [[180,200],[970,200],[180,670],[970,670]]){ctx.beginPath();ctx.moveTo(x-10,y);ctx.lineTo(x+10,y);ctx.moveTo(x,y-10);ctx.lineTo(x,y+10);ctx.stroke()}
ctx.fillStyle='#2e5369';ctx.fillRect(884,534,36,36);ctx.fillStyle='#e17c4e';ctx.fillRect(930,534,36,36);ctx.font='12px monospace';ctx.fillStyle='#68736d';ctx.fillText('INK 01 / 02',884,593);ctx.fillStyle='#3c4b4e';ctx.fillText('BOTANICAL IMPRESSION',140,704);ctx.textAlign='right';ctx.fillText('REGISTRATION '+String(reg).padStart(2,'0')+' PX',1060,704);ctx.restore()}
